{
  "@context": {
    "@language": "en",
    "@vocab": "https://schema.org/",
    "cr": "http://mlcommons.org/croissant/",
    "dct": "http://purl.org/dc/terms/",
    "sc": "https://schema.org/"
  },
  "@type": "cr:TaskProblem",
  "conformsTo": "http://mlcommons.org/croissant/1.0",
  "@id": "[FILL IN THE BLANK: paper_id]-task",
  "name": "Concordia Cooperative AI Challenge",
  "description": "Develop autonomous language model agents capable of cooperative reasoning, communication, and decision-making in text-mediated, multi-agent environments.",
  "paper_id": "[FILL IN THE BLANK: paper_id]",

  "cr:input": [
    {
      "@type": "cr:FileObject",
      "name": "Input Dataset",
      "description": "The input dataset consists of a single column named 'id' representing unique sample identifiers. Example values include 'sample_000', 'sample_001', etc.",
      "encodingFormat": "text/csv",
      "contentUrl": "[FILL IN THE BLANK: dataset source URL]"
    }
  ],

  "cr:output": {
    "name": "predictions",
    "description": "The output consists of predictions in CSV format with two columns: 'id' (matching input IDs) and 'pred' (predicted values as floats). Example values for 'pred' include 0.3456541535501251 and 0.8813422599917877.",
    "cr:schema": {
      "@type": "cr:RecordSet",
      "name": "prediction_schema",
      "field": [
        {
          "@type": "cr:Field",
          "name": "id",
          "dataType": "sc:Text",
          "description": "Unique identifier for each sample, matching the input dataset. Example values: 'sample_000', 'sample_001'."
        },
        {
          "@type": "cr:Field",
          "name": "pred",
          "dataType": "sc:Float",
          "description": "Predicted value for each sample. Example values: 0.3456541535501251, 0.8813422599917877."
        }
      ]
    }
  },

  "cr:implementation": {
    "cr:environment": {
      "language": "Python",
      "packages": ["numpy", "pandas", "scipy", "sklearn"]
    },
    "entryPoint": "solution.py",
    "interface": "predict(input_dir, output_dir)"
  },

  "cr:evaluation": {
    "primaryMetric": "LM-based reward model score",
    "metrics": ["LM-based reward model score", "Social Welfare", "Qualitative Analysis"],
    "higherIsBetter": true,
    "notes": "The primary metric is computed using Pearson correlation between ground truth and predictions. Secondary metric is mean squared error. Tertiary metric is qualitative analysis, which is a placeholder set to 0.0."
  },

  "cr:execution": {
    "runtimeLimitSec": 600,
    "memoryLimitMb": 4096,
    "allowedExternalData": "unknown"
  },

  "open_questions": [
    "The exact paper ID and DOI are not provided in the bundle.",
    "The dataset source URL is missing from the bundle."
  ],

  "fill_in_the_blank": [
    "paper_id - reason it could not be determined from the bundle files",
    "dataset.sourceUrl - reason it could not be determined from the bundle files"
  ]
}
